            outcomes.unwrap(),
            vec![
                NotificationOutcome::Dropped {
                    reason: Some(vf_pb::NotificationDropReason::RecipientBlocksActor)
                },
                NotificationOutcome::Allowed,
                NotificationOutcome::Failed,
                NotificationOutcome::Dropped {
                    reason: Some(vf_pb::NotificationDropReason::RecipientBlocksActor)
                },
                NotificationOutcome::Dropped {
                    reason: Some(vf_pb::NotificationDropReason::Unspecified)
                },
            ]
        );
