            [
                "incr vf_client_filter_notifications|requests=completed",
                "observe_vm vf_client_filter_notifications_batch_latency_ms_vm|result=success",
                "observe_vm vf_client_filter_notifications_latency_ms_vm",
            ]
        );
    }

